ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns fact http://factcorpws.etb.com/fact
---
{
    soapenv#Envelope: {
        soapenv#Header: null,
        soapenv#Body: {
        	fact#CobroRetiroAnticipado: {
        		xmlString: (write(payload,"application/xml", {"writeDeclaration": "false"}))
        	}
        }
    }
}

%dw 2.0
output application/json
var readPayload = read(payload.Envelope.Body.CobroRetiroAnticipadoResponse.return, "application/xml")
---
if (readPayload.replies.reply.response.sfilluminate != null)
{
	sfilluminate: readPayload.replies.reply.response.sfilluminate
}
else {
	"sfilluminate": {
        "resultado": "1",
        "descError": readPayload.replies.reply.response.faults.fault.fault_detail.@error_description
    }
}
